record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

if picking:
    for move in picking.move_ids.filtered(
        lambda m: m.state not in ('done', 'cancel')
    ):
        max_quantity = int(move.product_uom_qty)

        if max_quantity <= 0:
            max_quantity = 1

        seed = int(time.time()) + picking.id + move.id
        quantity = (seed % max_quantity) + 1

        # Guard cuối cùng
        quantity = max(1, quantity)

        move.write({
            'quantity': quantity,
        })
    activity_type = env.ref(
        'fmcg_business_automation.mail_activity_type_validate_assigned_picking'
    )
    picking.activity_schedule(
        activity_type_id=activity_type.id,
        summary='Validate assigned stock picking',
        user_id=env.user.id,
    )
